/* ChartPulse Global Styles */
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16162a;
  --bg-card: #13131f;
  --bg-hover: #1e1e32;
  --border-color: #2a2a40;
  --text-primary: #e8e8f0;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e4fd8;
  --green: #22c55e;
  --green-dim: #16a34a;
  --red: #F7525F;
  --red-dim: #dc2626;
  --yellow: #f59e0b;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

a {
  color: var(--accent-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: var(--bg-primary);
}
::-webkit-scrollbar-thumb {
  background: #3a3a50;
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: #4a4a60;
}

/* Utility */
.text-green { color: var(--green); }
.text-red { color: var(--red); }
.text-blue { color: var(--accent-blue); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }

.bg-card { background: var(--bg-card); }
.bg-secondary { background: var(--bg-secondary); }

.flex { display: flex; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.gap-1 { gap: 0.25rem; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.gap-4 { gap: 1rem; }

.w-full { width: 100%; }
.h-full { height: 100%; }

.p-2 { padding: 0.5rem; }
.p-3 { padding: 0.75rem; }
.p-4 { padding: 1rem; }
.px-3 { padding-left: 0.75rem; padding-right: 0.75rem; }
.px-4 { padding-left: 1rem; padding-right: 1rem; }
.py-2 { padding-top: 0.5rem; padding-bottom: 0.5rem; }
.py-3 { padding-top: 0.75rem; padding-bottom: 0.75rem; }

.rounded { border-radius: 0.5rem; }
.rounded-sm { border-radius: 0.25rem; }

.border { border: 1px solid var(--border-color); }
.border-b { border-bottom: 1px solid var(--border-color); }
.border-t { border-top: 1px solid var(--border-color); }

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-lg { font-size: 1.125rem; }
.text-xl { font-size: 1.25rem; }
.text-2xl { font-size: 1.5rem; }
.text-3xl { font-size: 1.875rem; }

.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }

.truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  border: none;
  transition: all 0.15s;
}

.btn-primary {
  background: var(--accent-blue);
  color: white;
}
.btn-primary:hover {
  background: var(--accent-blue-hover);
  text-decoration: none;
}

.btn-secondary {
  background: var(--bg-hover);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-secondary:hover {
  background: var(--border-color);
  text-decoration: none;
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
}
.btn-ghost:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
  text-decoration: none;
}

/* Tabs */
.tabs {
  display: flex;
  gap: 0.25rem;
  border-bottom: 1px solid var(--border-color);
}

.tab {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}

.tab:hover {
  color: var(--text-primary);
}

.tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.125rem 0.5rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 500;
}

.badge-green {
  background: rgba(34, 197, 94, 0.15);
  color: var(--green);
}

.badge-red {
  background: rgba(247, 82, 95, 0.15);
  color: var(--red);
}

.badge-blue {
  background: rgba(41, 98, 255, 0.15);
  color: var(--accent-blue);
}

.badge-gray {
  background: rgba(156, 163, 175, 0.15);
  color: var(--text-secondary);
}

/* Sparkline */
.sparkline {
  width: 80px;
  height: 30px;
}

/* Card */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  overflow: hidden;
}

.card-header {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-body {
  padding: 1rem;
}

/* Table */
.table-container {
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}

.data-table th {
  text-align: left;
  padding: 0.625rem 1rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
}

.data-table td {
  padding: 0.625rem 1rem;
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
}

.data-table tr:hover td {
  background: var(--bg-hover);
}

.data-table tr:last-child td {
  border-bottom: none;
}

/* Navigation */
.navbar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0 1rem;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-brand {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-brand:hover {
  text-decoration: none;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-link {
  padding: 0.375rem 0.75rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 0.375rem;
}

.nav-link:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
  text-decoration: none;
}

.nav-link.active {
  color: var(--accent-blue);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 2rem 1rem;
  margin-top: auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 2rem;
  max-width: 1200px;
  margin: 0 auto;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
  color: var(--text-primary);
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  color: var(--text-secondary);
  padding: 0.25rem 0;
}

.footer-col a:hover {
  color: var(--text-primary);
  text-decoration: none;
}

.footer-bottom {
  max-width: 1200px;
  margin: 1.5rem auto 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  text-align: center;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Page Layout */
.page-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1.5rem 1rem;
}

/* Section Title */
.section-title {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

/* Grid layouts */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}

/* Responsive */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .navbar { padding: 0 0.5rem; }
  .nav-links { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  animation: fadeIn 0.2s ease-out;
}

/* Toggle Switch */
.toggle-switch {
  position: relative;
  width: 40px;
  height: 22px;
  background: var(--border-color);
  border-radius: 11px;
  cursor: pointer;
  transition: background 0.2s;
}

.toggle-switch.on {
  background: var(--accent-blue);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 18px;
  height: 18px;
  background: white;
  border-radius: 50%;
  transition: transform 0.2s;
}

.toggle-switch.on::after {
  transform: translateX(18px);
}

/* Accordion */
.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem 0.75rem;
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-tertiary);
  border-bottom: 1px solid var(--border-color);
}

.accordion-header:hover {
  color: var(--text-primary);
}

.accordion-icon {
  transition: transform 0.2s;
  font-size: 0.75rem;
}

.accordion-header.collapsed .accordion-icon {
  transform: rotate(-90deg);
}

.accordion-body {
  overflow: hidden;
  transition: max-height 0.2s ease-out;
}

.accordion-body.collapsed {
  max-height: 0;
}

/* Chart toolbar */
.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.375rem 0.5rem;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  flex-wrap: wrap;
}

.toolbar-btn {
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: none;
  border: none;
  border-radius: 0.25rem;
  cursor: pointer;
}

.toolbar-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.toolbar-btn.active {
  background: var(--accent-blue);
  color: white;
}

.toolbar-separator {
  width: 1px;
  height: 18px;
  background: var(--border-color);
  margin: 0 0.25rem;
}

/* Watchlist item */
.watchlist-item {
  display: grid;
  grid-template-columns: 1fr auto auto auto;
  gap: 0.75rem;
  align-items: center;
  padding: 0.5rem 0.75rem;
  font-size: 0.8125rem;
  cursor: pointer;
  border-bottom: 1px solid var(--border-color);
}

.watchlist-item:hover {
  background: var(--bg-hover);
}

.watchlist-item .symbol {
  font-weight: 600;
  color: var(--text-primary);
}

.watchlist-item .last {
  color: var(--text-primary);
  text-align: right;
  min-width: 60px;
}

.watchlist-item .chg {
  text-align: right;
  min-width: 50px;
}

.watchlist-item .chg-pct {
  text-align: right;
  min-width: 50px;
}

/* Idea card */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  overflow: hidden;
  transition: border-color 0.15s;
}

.idea-card:hover {
  border-color: var(--border-color);
}

.idea-card-header {
  padding: 0.75rem 1rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.idea-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 600;
  color: white;
  flex-shrink: 0;
}

.idea-card-body {
  padding: 0 1rem 0.75rem;
}

.idea-card-footer {
  padding: 0.5rem 1rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Broker card */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  transition: border-color 0.15s;
}

.broker-card:hover {
  border-color: var(--accent-blue);
}

.broker-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.broker-name {
  font-size: 1rem;
  font-weight: 600;
}

.broker-tier {
  font-size: 0.75rem;
  padding: 0.125rem 0.5rem;
  border-radius: 0.25rem;
  font-weight: 500;
}

.broker-tier.platinum {
  background: linear-gradient(135deg, #6b7280 0%, #374151 100%);
  color: #e5e7eb;
}

.broker-tier.gold {
  background: linear-gradient(135deg, #d97706 0%, #92400e 100%);
  color: #fef3c7;
}

.broker-rating {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.broker-rating-score {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent-blue);
}

.broker-stats {
  display: flex;
  gap: 1rem;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.broker-promo {
  font-size: 0.875rem;
  color: var(--green);
  font-weight: 500;
}

/* Stats banner */
.stats-banner {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  padding: 1.5rem;
  text-align: center;
}

.stats-banner-value {
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent-blue);
}

.stats-banner-label {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-top: 0.25rem;
}

/* Mini chart canvas */
.mini-chart {
  width: 100%;
  height: 40px;
}

/* News card */
.news-card {
  display: flex;
  gap: 1rem;
  padding: 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
}

.news-image {
  width: 120px;
  height: 80px;
  background: var(--bg-tertiary);
  border-radius: 0.375rem;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 0.75rem;
}

.news-content {
  flex: 1;
  min-width: 0;
}

.news-title {
  font-weight: 600;
  margin-bottom: 0.25rem;
  line-height: 1.4;
}

.news-meta {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Market summary bar */
.market-bar {
  display: flex;
  gap: 1.5rem;
  padding: 0.75rem 1rem;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  overflow-x: auto;
  white-space: nowrap;
}

.market-bar-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
}

.market-bar-name {
  color: var(--text-secondary);
}

.market-bar-price {
  font-weight: 600;
  color: var(--text-primary);
}

.market-bar-change {
  font-weight: 500;
}

/* Hero */
.hero {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 3rem 1rem;
  text-align: center;
}

.hero-title {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  line-height: 1.2;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 1.5rem;
}

.hero-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* Stock detail panel */
.detail-panel {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  padding: 1rem;
}

.detail-header {
  margin-bottom: 1rem;
}

.detail-ticker {
  font-size: 1.5rem;
  font-weight: 700;
}

.detail-name {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.detail-price {
  font-size: 2rem;
  font-weight: 700;
}

.detail-change {
  font-size: 1rem;
  font-weight: 500;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
  margin-top: 1rem;
}

.detail-item {
  font-size: 0.875rem;
}

.detail-item-label {
  color: var(--text-secondary);
  font-size: 0.75rem;
}

.detail-item-value {
  font-weight: 500;
  margin-top: 0.125rem;
}

/* Candlestick chart area */
.chart-area {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 0.25rem;
  position: relative;
  overflow: hidden;
}

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  margin-top: 1.5rem;
}

.page-btn {
  padding: 0.375rem 0.625rem;
  font-size: 0.875rem;
  border-radius: 0.25rem;
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  color: var(--text-secondary);
  cursor: pointer;
}

.page-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.page-btn.active {
  background: var(--accent-blue);
  color: white;
  border-color: var(--accent-blue);
}

/* Yield curve bar */
.yield-bar {
  height: 8px;
  background: var(--border-color);
  border-radius: 4px;
  overflow: hidden;
  margin-top: 0.25rem;
}

.yield-bar-fill {
  height: 100%;
  background: var(--accent-blue);
  border-radius: 4px;
}

// ChartPulse Main JavaScript

// Tab switching utility
function initTabs(containerSelector, tabSelector, panelSelector, callback) {
  const containers = document.querySelectorAll(containerSelector);
  containers.forEach(container => {
    const tabs = container.querySelectorAll(tabSelector);
    const panels = container.querySelectorAll(panelSelector);

    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        const target = tab.dataset.tab;

        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        panels.forEach(p => {
          if (p.dataset.panel === target) {
            p.classList.remove('hidden');
            p.classList.add('fade-in');
          } else {
            p.classList.add('hidden');
            p.classList.remove('fade-in');
          }
        });

        if (callback) callback(target, tab);
      });
    });
  });
}

// Accordion utility
function initAccordions(selector) {
  const headers = document.querySelectorAll(selector);
  headers.forEach(header => {
    header.addEventListener('click', () => {
      const body = header.nextElementSibling;
      const isCollapsed = header.classList.contains('collapsed');

      if (isCollapsed) {
        header.classList.remove('collapsed');
        body.classList.remove('collapsed');
        body.style.maxHeight = body.scrollHeight + 'px';
      } else {
        header.classList.add('collapsed');
        body.classList.add('collapsed');
        body.style.maxHeight = '0';
      }
    });
  });
}

// Toggle switch utility
function initToggleSwitches(selector, callback) {
  const switches = document.querySelectorAll(selector);
  switches.forEach(sw => {
    sw.addEventListener('click', () => {
      sw.classList.toggle('on');
      if (callback) callback(sw.classList.contains('on'), sw);
    });
  });
}

// Generate random sparkline path
function generateSparkline(width, height, points = 20, trend = 'random') {
  const step = width / (points - 1);
  let y = height / 2;
  let path = `M0,${y}`;

  for (let i = 1; i < points; i++) {
    const change = trend === 'up' 
      ? (Math.random() - 0.3) * height * 0.3
      : trend === 'down'
      ? (Math.random() - 0.7) * height * 0.3
      : (Math.random() - 0.5) * height * 0.4;
    y = Math.max(2, Math.min(height - 2, y + change));
    path += ` L${i * step},${y}`;
  }

  return path;
}

// Draw sparkline on SVG element
function drawSparkline(svgId, trend = 'random', color = null) {
  const svg = document.getElementById(svgId);
  if (!svg) return;

  const width = svg.clientWidth || 80;
  const height = svg.clientHeight || 30;
  const pathData = generateSparkline(width, height, 25, trend);

  const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  path.setAttribute('d', pathData);
  path.setAttribute('fill', 'none');
  path.setAttribute('stroke', color || (trend === 'up' ? '#22c55e' : trend === 'down' ? '#F7525F' : '#9ca3af'));
  path.setAttribute('stroke-width', '1.5');
  path.setAttribute('stroke-linecap', 'round');
  path.setAttribute('stroke-linejoin', 'round');

  svg.innerHTML = '';
  svg.appendChild(path);
}

// Draw mini area chart
function drawMiniAreaChart(canvasId, dataPoints, color) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;

  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 120;
  const height = canvas.height = canvas.clientHeight || 40;

  const min = Math.min(...dataPoints);
  const max = Math.max(...dataPoints);
  const range = max - min || 1;

  ctx.clearRect(0, 0, width, height);

  // Gradient fill
  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, color + '40');
  gradient.addColorStop(1, color + '05');

  ctx.beginPath();
  ctx.moveTo(0, height);

  dataPoints.forEach((val, i) => {
    const x = (i / (dataPoints.length - 1)) * width;
    const y = height - ((val - min) / range) * height * 0.8 - height * 0.1;
    ctx.lineTo(x, y);
  });

  ctx.lineTo(width, height);
  ctx.closePath();
  ctx.fillStyle = gradient;
  ctx.fill();

  // Line
  ctx.beginPath();
  dataPoints.forEach((val, i) => {
    const x = (i / (dataPoints.length - 1)) * width;
    const y = height - ((val - min) / range) * height * 0.8 - height * 0.1;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.strokeStyle = color;
  ctx.lineWidth = 1.5;
  ctx.stroke();
}

// Generate random candlestick data
function generateCandleData(count = 100) {
  const data = [];
  let price = 260;

  for (let i = 0; i < count; i++) {
    const open = price;
    const change = (Math.random() - 0.48) * 6;
    const close = open + change;
    const high = Math.max(open, close) + Math.random() * 3;
    const low = Math.min(open, close) - Math.random() * 3;

    data.push({ open, high, low, close });
    price = close;
  }

  return data;
}

// Draw candlestick chart
function drawCandlestickChart(canvasId, data, timeframe = '1D') {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;

  const ctx = canvas.getContext('2d');
  const rect = canvas.getBoundingClientRect();
  const width = canvas.width = rect.width;
  const height = canvas.height = rect.height;

  ctx.clearRect(0, 0, width, height);

  // Grid lines
  ctx.strokeStyle = '#2a2a40';
  ctx.lineWidth = 0.5;
  for (let i = 1; i < 5; i++) {
    const y = (height / 5) * i;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(width, y);
    ctx.stroke();
  }
  for (let i = 1; i < 6; i++) {
    const x = (width / 6) * i;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();
  }

  if (!data || data.length === 0) return;

  const visibleData = data.slice(-Math.floor(width / 8));
  const candleWidth = Math.max(2, (width / visibleData.length) * 0.7);
  const spacing = width / visibleData.length;

  const prices = visibleData.flatMap(d => [d.high, d.low]);
  const minPrice = Math.min(...prices);
  const maxPrice = Math.max(...prices);
  const priceRange = maxPrice - minPrice || 1;

  const padding = height * 0.05;
  const chartHeight = height - padding * 2;

  const priceToY = (p) => padding + chartHeight - ((p - minPrice) / priceRange) * chartHeight;

  visibleData.forEach((candle, i) => {
    const x = i * spacing + spacing / 2;
    const yOpen = priceToY(candle.open);
    const yClose = priceToY(candle.close);
    const yHigh = priceToY(candle.high);
    const yLow = priceToY(candle.low);

    const isGreen = candle.close >= candle.open;
    ctx.fillStyle = isGreen ? '#22c55e' : '#F7525F';
    ctx.strokeStyle = isGreen ? '#22c55e' : '#F7525F';

    // Wick
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, yHigh);
    ctx.lineTo(x, yLow);
    ctx.stroke();

    // Body
    const bodyTop = Math.min(yOpen, yClose);
    const bodyHeight = Math.max(1, Math.abs(yOpen - yClose));
    ctx.fillRect(x - candleWidth / 2, bodyTop, candleWidth, bodyHeight);
  });

  // Price labels on right
  ctx.fillStyle = '#9ca3af';
  ctx.font = '10px Inter, sans-serif';
  ctx.textAlign = 'left';
  for (let i = 0; i <= 4; i++) {
    const price = minPrice + (priceRange * i) / 4;
    const y = padding + chartHeight - (chartHeight * i) / 4;
    ctx.fillText(price.toFixed(2), width - 45, y + 3);
  }
}

